import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { parseNotices } from "./notices";

const sample = [
  "# Third-party notices",
  "",
  "App is MIT licensed.",
  "Generated by `scripts/notices.sh`.",
  "",
  "Second paragraph.",
  "",
  "## MIT",
  "",
  "- [react](https://github.com/react/react) 19.3.1 (npm)",
  "- [scheduler](https://github.com/react/react) 0.28.0 (npm)",
  "",
  "```text",
  "MIT License",
  "",
  "Copyright (c) Meta",
  "```",
  "",
  "- [vite](https://github.com/vitejs/vite) 8.3.5 (npm)",
  "",
  "````text",
  "has ``` inside",
  "````",
  "",
  "## BSD-3-Clause",
  "",
  "- [Go standard library and runtime](https://go.dev) (Go)",
  "",
  "```text",
  "Copyright 2009 The Go Authors.",
  "```",
  "",
].join("\n");

describe("parseNotices", () => {
  it("reads the intro, the licences and the texts they share", () => {
    const n = parseNotices(sample);
    expect(n.intro).toEqual([
      "App is MIT licensed. Generated by scripts/notices.sh.",
      "Second paragraph.",
    ]);
    expect(n.licences.map((l) => l.id)).toEqual(["MIT", "BSD-3-Clause"]);
    const [mit, bsd] = n.licences;
    expect(mit.texts).toHaveLength(2);
    expect(mit.texts[0].components).toEqual([
      { name: "react", url: "https://github.com/react/react", detail: "19.3.1 (npm)" },
      { name: "scheduler", url: "https://github.com/react/react", detail: "0.28.0 (npm)" },
    ]);
    expect(mit.texts[0].text).toBe("MIT License\n\nCopyright (c) Meta");
    expect(mit.texts[1].text).toBe("has ``` inside");
    expect(bsd.texts[0].components[0]).toEqual({
      name: "Go standard library and runtime",
      url: "https://go.dev",
      detail: "(Go)",
    });
  });

  it("parses the committed THIRD_PARTY_NOTICES.md", () => {
    const md = readFileSync(new URL("../../../THIRD_PARTY_NOTICES.md", import.meta.url), "utf8");
    const n = parseNotices(md);
    expect(n.licences.length).toBeGreaterThan(0);
    for (const l of n.licences) {
      expect(l.texts.length, l.id).toBeGreaterThan(0);
      for (const t of l.texts) {
        expect(t.components.length, l.id).toBeGreaterThan(0);
        expect(t.text.length, l.id).toBeGreaterThan(0);
      }
    }
    const names = n.licences.flatMap((l) =>
      l.texts.flatMap((t) => t.components.map((c) => c.name)),
    );
    expect(names).toContain("react");
    expect(names).toContain("github.com/wailsapp/wails/v2");
  });
});
